def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    # Metnin sonundaki tek satır sonunu dikkate almamak için:
    # splitlines() metin sonunda \n varsa boş satır eklemez.
    # Örn: "a\n".splitlines() -> ["a"]
    # Örn: "a\n\n".splitlines() -> ["a", ""]
    # Bu davranış kuralımızla uyumlu.

    lines = text.splitlines()

    # Metin sadece newline karakterlerinden oluşuyorsa [] dönmeli (kural gereği)
    if all(c in "\r\n" for c in text):
        return []

    results = []
    for line in lines:
        results.append(_parse_line(line, delimiter))

    return results

def _parse_line(line: str, delimiter: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)

    # Eğer satır tamamen boşsa (splitlines boş satırı "" olarak döner)
    if not line:
        return [""]

    while i < n:
        if line[i] == '"':
            # Tırnaklı alan başlangıcı
            i += 1
            field_content = ""
            found_end_quote = False

            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        # Kaçış tırnağı ""
                        field_content += '"'
                        i += 2
                    else:
                        # Tırnak kapandı
                        found_end_quote = True
                        i += 1
                        break
                else:
                    field_content += line[i]
                    i += 1

            if not found_end_quote:
                raise ValueError("Kapanmayan tırnak.")

            fields.append(field_content)

            # Tırnaktan hemen sonra ayırıcı veya satır sonu gelmeli
            # splitlines satır sonunu kestiği için i == n durumunu kontrol etmeliyiz
            if i < n:
                if line[i] == delimiter:
                    i += 1
                    # Eğer delimiter satır sonunda ise (örn: "a",), boş bir alan ekle
                    if i == n:
                        fields.append("")
                else:
                    raise ValueError(f"Hatalı karakter: '{line[i]}' tırnaktan hemen sonra gelemez.")

        else:
            # Tırnaksız alan
            start = i
            while i < n and line[i] != delimiter:
                # Tırnaksız alan içinde tırnak varsa sıradan karakter sayılır (kural gereği)
                i += 1

            field_content = line[start:i]
            fields.append(field_content)

            if i < n and line[i] == delimiter:
                i += 1
                if i == n:
                    fields.append("")

    # Eğer satır sonuna kadar tırnaksız bir delimiter ile gelindiyse ve boşsa
    # (splitlines zaten handle ediyor ama kontrol etmekte fayda var)

    return fields

