    fields = []
    i = 0
    n = len(line)

    if i == n:
        return [""]

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            field_content = ""
            found_end_quote = False
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field_content += '"'
                        i += 2
                    else:
                        found_end_quote = True
                        i += 1
                        break
                else:
                    field_content += line[i]
                    i += 1

            if not found_end_quote:
                raise ValueError("Kapanmayan tırnak.")

            fields.append(field_content)

            # After closing quote, check for delimiter or end of line
            if i < n:
                if line[i] == delimiter:
                    i += 1
                    if i == n:
                        fields.append("")
                else:
                    raise ValueError(f"Hatalı karakter: '{line[i]}' tırnaktan hemen sonra gelemez.")
            elif i == n:
                # If we reached end of line immediately after quote
                pass
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != delimiter:
                i += 1
            field_content = line[start:i]
            fields.append(field_content)

            if i < n and line[i] == delimiter:
                i += 1
                if i == n:
                    fields.append("")
            elif i == n and start == i:
                # This handles the case where the line ends with a delimiter
                # But the while loop logic already handles it via the delimiter check
                pass

    # If the line was empty or we didn't process anything (shouldn't happen with i < n check)
    # but for safety, if the last field is empty and we are at end of string
    # we need to ensure we didn't miss a trailing empty field.
    # Actually, the logic `if i < n and line[i] == delimiter: fields.append("")` covers it.

    # If the line is just empty (but not the end of the string), 
    # splitlines handles it, but we must ensure a single empty line returns [""]
    return fields

